        f'<p>{bi(vendor_th, vendor_en)}</p>'
        f'<p><a href="claim.html">🏪 {bi("ร้านอยู่แล้ว? ยืนยันเลย", "Already listed? Claim it")}</a></p></div>'
        f'<div class="module"><h3>🚶 {bi("สำหรับคนทั่วไป", "For everyone else")}</h3>'
