        f'{bi("ส่งผ่าน GitHub", "Suggest via GitHub")}</a> · '
        f'<a href="{KOFI}" rel="noopener">{bi("ฝากข้อความทาง Ko-fi", "Message us on Ko-fi")}</a></p>'
